// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length > 0);
        vm.assume(v.length == _tos.length);
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        (bool ok, bytes memory ret) = address(c).call(abi.encodeWithSelector(c.transfer.selector, _tos, v));
        vm.assume(ok == true && ret.length == 32);
        bool returned = abi.decode(ret, (bool));
        assertTrue(returned == true);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address[] memory _tos, uint[] memory v) public payable {
        require(true);
        bool reverted; try c.transfer(_tos, v) { reverted = false; } catch { reverted = true; }
        assert(msg.sender != 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9 ? reverted == true : true);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(caller != 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        bool reverted; try c.transfer(new address[](1), new uint[](1)) { reverted = false; } catch { reverted = true; }
        assert(reverted == true);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, address[] memory tos, uint[] memory vs) public payable {
        require(tos.length == vs.length && tos.length > 0);
        bool reverted;
        try c.transfer(tos, vs) { reverted = false; } catch { reverted = true; }
        assert(!reverted || caller != 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address[] memory _tos, uint[] memory v, address sender) public payable {
        require(sender != 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        bool reverted; try c.transfer(_tos, v) { reverted = false; } catch { reverted = true; }
        assert(reverted == true);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address[] memory _tos, uint[] memory v, address caller) public payable {
        require(true);
        bool reverted;
        if (caller != 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9) {
            try c.transfer(_tos, v) { reverted = false; } catch { reverted = true; }
            assert(reverted == true);
        } else {
            assert(true);
        }
    }
}
